module CRC_MEAN

using LinearAlgebra

export velocity_blocks, mean_convective_mode, second_order_wall_values,
       mean_similarity_correction

"""Extract (u,v,w) Chebyshev blocks from the raw four-field state vector."""
function velocity_blocks(q::AbstractVector, N::Integer)
    n = N + 1
    length(q) == 4n || throw(DimensionMismatch("four-field state"))
    return q[1:n], q[n+1:2n], q[2n+1:3n]
end

"""Mean convective acceleration generated by one complex Fourier mode.

The physical real perturbation is Re(qhat(z)*exp(i*(kappa*r+n*theta))).
The returned profiles are phase averages of (q1·grad)q1 in cylindrical
coordinates at a frozen radius R. The vector is (radial, azimuthal, axial).
This is a diagnostic forcing profile; its sign must be negated when inserted
as a right-hand-side body force in the momentum equation.
"""
function mean_convective_mode(q::AbstractVector, D::AbstractMatrix,
                             N::Integer, kappa::Real, nmode::Real, R::Real)
    ur, ut, uz = velocity_blocks(q, N)
    dur, dut, duz = D * ur, D * ut, D * uz
    ik = im * kappa
    in_over_R = im * nmode / R

    ar = 0.5 .* real.(conj.(ur) .* (ik .* ur) .+
                       conj.(ut) .* (in_over_R .* ur) .+
                       conj.(uz) .* dur) .-
         0.5 .* abs2.(ut) ./ R

    atheta = 0.5 .* real.(conj.(ur) .* (ik .* ut) .+
                           conj.(ut) .* (in_over_R .* ut) .+
                           conj.(uz) .* dut) .+
             0.5 .* real.(conj.(ur) .* ut) ./ R

    az = 0.5 .* real.(conj.(ur) .* (ik .* uz) .+
                       conj.(ut) .* (in_over_R .* uz) .+
                       conj.(uz) .* duz)
    return (; radial=ar, azimuthal=atheta, axial=az)
end

"""Second-order mean wall values from a graph displacement.

For h=Re(hhat*exp(i phase)) and q1=Re(qhat*exp(i phase)), the zero-phase
part of the Taylor-expanded no-slip condition is returned for (u,v,w). The
formula omits slope/normal-vector terms; those are added when a finite-slope
roughness geometry is promoted beyond this local pilot.
"""
function second_order_wall_values(flow, qhat, hhat, D, D2, N::Integer)
    ur, ut, uz = velocity_blocks(qhat, N)
    dur, dut, duz = D * ur, D * ut, D * uz
    F, G, H = vec(flow.F), vec(flow.G), vec(flow.H)
    Fzz, Gzz, Hzz = D2 * F, D2 * G, D2 * H
    return (
        -0.5 * real(conj(hhat) * dur[1]) - 0.25 * abs2(hhat) * Fzz[1],
        -0.5 * real(conj(hhat) * dut[1]) - 0.25 * abs2(hhat) * Gzz[1],
        -0.5 * real(conj(hhat) * duz[1]) - 0.25 * abs2(hhat) * Hzz[1])
end

"""Solve the frozen-R similarity Jacobian forced by mean radial/azimuthal acceleration.

This is a local pilot, not a full r-z base-flow solver. It differentiates the
mode-1 von-Karman ODE residual, keeps homogeneous/second-order wall values,
and uses the differentiated radial equation so the constant radial-pressure
parameter drops out. `ar` and `atheta` are phase-averaged convective
accelerations; their negatives are momentum right-hand-side forces.
"""
function mean_similarity_correction(flow, D::AbstractMatrix, RE::Real,
                                    ar::AbstractVector, atheta::AbstractVector;
                                    wall_values=(0.0, 0.0, 0.0))
    n = length(flow.z)
    length(ar) == n && length(atheta) == n ||
        throw(DimensionMismatch("mean forcing length"))
    D2, D3 = D * D, D * D * D
    F, G, H = vec(flow.F), vec(flow.G), vec(flow.H)
    Fp, Gp, Hp = D * F, D * G, D * H
    Fpp = D2 * F
    s = sqrt(RE)
    m = n - 2
    A = zeros(Float64, 3n, 3n)
    b = zeros(Float64, 3n)
    fi, gi, hi = 1:n, n+1:2n, 2n+1:3n
    rows_c, rows_r, rows_t = 1:m, m+1:2m, 2m+1:3m
    interior = 2:n-1
    put!(A, rows, cols, block) = (A[rows, cols] .+= block)

    # h' + 2 sqrt(Re) f = 0
    put!(A, rows_c, fi, 2s .* Matrix{Float64}(I, m, n)[1:m, :])
    put!(A, rows_c, hi, D[interior, :])

    # Differentiated radial-momentum equation.
    radial_f = D3[interior, :] - (RE / s) .* Diagonal(H[interior]) * D2[interior, :] -
               (RE / s) .* Diagonal(Hp[interior]) * D[interior, :] -
               2RE .* Diagonal(Fp[interior]) * Matrix{Float64}(I, m, n)[1:m, :] -
               2RE .* Diagonal(F[interior]) * D[interior, :]
    radial_g = 2RE .* Diagonal(Gp[interior]) * Matrix{Float64}(I, m, n)[1:m, :] +
               2RE .* Diagonal(G[interior]) * D[interior, :]
    radial_h = -(RE / s) .* Diagonal(Fpp[interior]) * Matrix{Float64}(I, m, n)[1:m, :] -
               (RE / s) .* Diagonal(Fp[interior]) * D[interior, :]
    put!(A, rows_r, fi, radial_f)
    put!(A, rows_r, gi, radial_g)
    put!(A, rows_r, hi, radial_h)
    b[rows_r] .= -RE .* (D * ar)[interior]

    # Azimuthal-momentum equation.
    theta_f = -2RE .* Diagonal(G[interior]) * Matrix{Float64}(I, m, n)[1:m, :]
    theta_g = D2[interior, :] - (RE / s) .* Diagonal(H[interior]) * D[interior, :] -
               2RE .* Diagonal(F[interior]) * Matrix{Float64}(I, m, n)[1:m, :]
    theta_h = -(RE / s) .* Diagonal(Gp[interior]) * Matrix{Float64}(I, m, n)[1:m, :]
    put!(A, rows_t, fi, theta_f)
    put!(A, rows_t, gi, theta_g)
    put!(A, rows_t, hi, theta_h)
    b[rows_t] .= -RE .* atheta[interior]

    # Three variables are prescribed at each wall. The upper wall is smooth.
    row = 3m
    for (field, value) in ((fi, wall_values[1]), (gi, wall_values[2]),
                           (hi, wall_values[3]))
        row += 1; A[row, field[1]] = 1; b[row] = value
        row += 1; A[row, field[end]] = 1; b[row] = 0
    end
    x = A \ b
    return (; F2=x[fi], G2=x[gi], H2=x[hi], matrix=A, rhs=b,
            residual=norm(A*x-b)/max(norm(b), 1.0))
end

end
